preConditionHook:
// THE FINAL FLAG'S REVERSAL FAILS AND THE TREND RESUMES. A final-flag reversal
// triggers -- price closes out of the flag on the countertrend side -- and
// within a couple of bars price closes back through THAT SIGNAL BAR'S OWN
// extreme. The reversal was the trap; the original trend is going again, so
// this is a breakout-pullback entry WITH it. A failed bear reversal is a long;
// a failed bull reversal a short.
//
// The three-push twin of this rule is FailedThreePushReversalContinuation,
// kept separate because the precondition is a different pattern, so different
// bars. The two are listed on each other as near-misses.
//
// THE PRECONDITION IS THE PLAIN FLAG BREAK, without
// FinalFlagReversalBreakoutEntry's optional prior-breakout term: that input
// would double the state this rule already carries with no source behind it,
// so the flag here is always the flagBars bars ending one bar ago. Recorded,
// not hidden.
//
// STATE, two variables per side. When the flag's countertrend break fires, the
// age is set to 0 and the SIGNAL BAR'S own extreme is latched -- its high for
// a bear signal, its low for a bull one, which is the level a failure has to
// close back through. Every later bar ages the pending signal BEFORE the
// failure test reads it, so the test only ever refers to a bar strictly in the
// past, and the latch happens AFTER the test so a signal cannot fail on its
// own bar. An age of -1 means nothing is pending.
//
// FinalFlagCandidate is inlined and read one bar back (candPrev), as in
// FinalFlagReversalBreakoutEntry; its parts are the standing always-in
// decision and V07-01's overlap definition, and the MinList / MaxList note is
// there too. The flag extremes are scanned by hand, seeded on the window's
// first bar with a STRICT comparison, which is what EL's Extremes does, and
// with el_gt / el_lt so it carries the relational tolerance.
//
// Deepest bar touched: flagBars, or consecutiveBars - 1 if that is larger.
candPrev = isCandidate;
allBull = true;
allBear = true;
for (int k = 0; k < (int)consecutiveBars; ++k) {
    rng = high[k] - low[k];
    if (el_le(close[k], open[k])) allBull = false;
    if (el_lt(close[k] - open[k], bodyFraction * rng)) allBull = false;
    if (el_gt(high[k] - close[k], tailFraction * rng)) allBull = false;
    if (el_gt(open[k] - low[k], tailFraction * rng)) allBull = false;
    if (el_ge(close[k], open[k])) allBear = false;
    if (el_lt(open[k] - close[k], bodyFraction * rng)) allBear = false;
    if (el_gt(close[k] - low[k], tailFraction * rng)) allBear = false;
    if (el_gt(high[k] - open[k], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    aiBars = 0;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    aiBars = 0;
    flipped = true;
}
if (flipped == false) aiBars = aiBars + 1;
ovCount = 0;
for (int k = 0; k < (int)flagBars; ++k) {
    ovBar = (high[k] < high[k + 1] ? high[k] : high[k + 1])
            - (low[k] > low[k + 1] ? low[k] : low[k + 1]);
    if (el_lt(ovBar, 0.0)) ovBar = 0.0;
    if (el_ge(ovBar, overlapThreshold * (high[k + 1] - low[k + 1]))) ovCount = ovCount + 1;
}
isCandidate = (aiDir != 0) && ((double)aiBars >= minTrendBars) && el_ge((double)ovCount, minOverlapFraction * flagBars);
flagHigh = high[1];
flagLow = low[1];
for (int k = 2; k <= (int)flagBars; ++k) {
    if (el_gt(high[k], flagHigh)) flagHigh = high[k];
    if (el_lt(low[k], flagLow)) flagLow = low[k];
}
revUpNow = candPrev && el_gt(close[0], flagHigh);
revDnNow = candPrev && el_lt(close[0], flagLow);
if (dnSigAge >= 0) dnSigAge = dnSigAge + 1;
if (upSigAge >= 0) upSigAge = upSigAge + 1;
resumeLong = (dnSigAge >= 1) && ((double)dnSigAge <= failureWindowBars) && el_gt(close[0], dnSigHigh);
resumeShort = (upSigAge >= 1) && ((double)upSigAge <= failureWindowBars) && el_lt(close[0], upSigLow);
if (revDnNow) {
    dnSigAge = 0;
    dnSigHigh = high[0];
}
if (revUpNow) {
    upSigAge = 0;
    upSigLow = low[0];
}
